sys_variable_value.value:
(function execute(inputs, outputs) {
    var r = new x_snc_vendor.VendorRiskUtils().calculateRiskScore(inputs.vendor_sys_id);
    outputs.score = r.score;
    outputs.level = r.level;
})(inputs, outputs);

